CREATE OR REPLACE FUNCTION public.check_gallery_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (
    select count(*)
    from public.provider_gallery_images
    where provider_id = new.provider_id
  ) >= 12 then
    raise exception 'gallery_limit_exceeded'
      using hint = 'En fazla 12 is gorseli yukleyebilirsiniz.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_audit_logs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  deleted_count integer := 0;
begin
  delete from public.audit_logs
  where created_at < timezone('utc', now()) - interval '90 days'
    and action not like 'security.%';

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_payout_preconditions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_open_dispute integer;
begin
  select status into v_status
  from public.orders
  where id = new.order_id;

  if v_status is null then
    raise exception 'Payout icin order bulunamadi (order_id=%).', new.order_id;
  end if;

  if v_status <> 'APPROVED' then
    raise exception 'Payout yalnizca APPROVED order icin olusturulabilir (mevcut durum=%).', v_status;
  end if;

  select count(*) into v_open_dispute
  from public.disputes
  where order_id = new.order_id
    and status in ('OPEN', 'UNDER_REVIEW');

  if v_open_dispute > 0 then
    raise exception 'Acik dispute varken payout olusturulamaz (order_id=%).', new.order_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_service_request_assigned_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.assigned_provider_id is not null
     and (tg_op = 'INSERT' or old.assigned_provider_id is null) then
    new.assigned_at := timezone('utc', now());
  end if;

  if new.assigned_provider_id is null then
    new.assigned_at := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_provider_review(p_provider_id uuid, p_rating smallint, p_comment text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_review_id uuid;
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'review-auth-required'
      using errcode = '42501';
  end if;

  if p_rating is null or p_rating not between 1 and 5 then
    raise exception 'review-rating-invalid'
      using errcode = '22023';
  end if;

  if p_comment is null
    or char_length(btrim(p_comment)) < 10
    or char_length(btrim(p_comment)) > 1000
  then
    raise exception 'review-comment-invalid'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.service_requests request
    where request.user_id = v_user_id
      and request.assigned_provider_id = p_provider_id
      and request.status = 'completed'
  ) then
    raise exception 'review-not-eligible'
      using errcode = '42501';
  end if;

  insert into public.reviews (
    provider_id,
    user_id,
    rating,
    comment
  )
  values (
    p_provider_id,
    v_user_id,
    p_rating,
    btrim(p_comment)
  )
  returning id into v_review_id;

  update public.providers provider
  set
    rating = summary.average_rating,
    review_count = summary.review_count
  from (
    select
      round(avg(review.rating)::numeric, 1) as average_rating,
      count(*)::integer as review_count
    from public.reviews review
    where review.provider_id = p_provider_id
  ) summary
  where provider.id = p_provider_id;

  return v_review_id;
exception
  when unique_violation then
    raise exception 'review-already-submitted'
      using errcode = '23505';
end;
$function$
